package com.termux.app.workspace;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.zip.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class DictationModelTest {
 @Rule public TemporaryFolder folder=new TemporaryFolder();
 static byte[] zip(String extra)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){for(String name:new String[]{"am/final.mdl","conf/model.conf","graph/Gr.fst","graph/HCLr.fst",extra}){if(name==null)continue;z.putNextEntry(new ZipEntry(DictationModel.ROOT+"/"+name));z.write(new byte[]{1,2,3});z.closeEntry();}}return out.toByteArray();}
 static String sha(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",n&255));return s.toString();}
 @Test public void verifiedArchiveIsAtomicAndCacheReusesOnlyReadyModel()throws Exception{byte[] zip=zip(null);Path cache=folder.newFolder().toPath();File model=DictationModel.extract(new ByteArrayInputStream(zip),cache,sha(zip),()->false);assertTrue(new File(model,"am/final.mdl").isFile());assertEquals(model,DictationModel.extract(new ByteArrayInputStream(new byte[0]),cache,sha(zip),()->false));assertEquals(1,Files.list(cache).count());}
 @Test public void wrongHashAndUnsafePathLeaveNoCommittedModel()throws Exception{for(byte[] zip:new byte[][]{zip(null),zip("../../outside")}){Path cache=folder.newFolder().toPath();try{DictationModel.extract(new ByteArrayInputStream(zip),cache,zip.length==zip(null).length?String.join("",Collections.nCopies(64,"0")):sha(zip),()->false);fail();}catch(IOException expected){}assertEquals(0,Files.list(cache).count());assertFalse(Files.exists(cache.resolve("outside")));}}
 @Test public void cancelLeavesNoPartialCacheAndExistingFilesUntouched()throws Exception{byte[] zip=zip(null);Path cache=folder.newFolder().toPath();Path held=cache.resolve("user-file");Files.write(held,new byte[]{7});try{DictationModel.extract(new ByteArrayInputStream(zip),cache,sha(zip),()->true);fail();}catch(InterruptedIOException expected){}assertArrayEquals(new byte[]{7},Files.readAllBytes(held));assertEquals(1,Files.list(cache).count());}
 @Test public void incompleteDestinationIsNotDeleted()throws Exception{byte[] zip=zip(null);Path cache=folder.newFolder().toPath();Path old=Files.createDirectory(cache.resolve("ru-0.22-"+sha(zip).substring(0,12)));Files.write(old.resolve("kept"),new byte[]{5});try{DictationModel.extract(new ByteArrayInputStream(zip),cache,sha(zip),()->false);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("incomplete"));}assertTrue(Files.exists(old.resolve("kept")));}
}
